for conn in [4,8]:
 seen=set(); comps=[]
 for r in range(A.shape[0]):
  for c in range(A.shape[1]):
   if A[r,c]==0 and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); co=[]
    while q:
     x,y=q.pop(); co.append((x,y))
     for dx,dy in ([(1,0),(-1,0),(0,1),(0,-1)] if conn==4 else [(i,j) for i in [-1,0,1] for j in [-1,0,1] if i or j]):
      u,v=x+dx,y+dy
      if 0<=u<A.shape[0] and 0<=v<A.shape[1] and A[u,v]==0 and (u,v) not in seen: seen.add((u,v)); q.append((u,v))
    comps.append(co)
 print(conn, len(comps), sorted(map(len,comps),reverse=True)[:20])
 # classify components changed count
 print(sorted([(len(co),sum(B[x,y]==8 for x,y in co), min(co)) for co in comps],reverse=True)[:20])

