# 8-neighbor distance from 8 seeds through cells not equal 2
D=np.full(A.shape,999); q=deque()
for p in coords8: D[p]=0;q.append(p)
while q:
 r,c=q.popleft()
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   nr,nc=r+dr,c+dc
   if (dr or dc) and 0<=nr<A.shape[0] and 0<=nc<A.shape[1] and A[nr,nc]!=2 and D[nr,nc]>D[r,c]+1:
    D[nr,nc]=D[r,c]+1;q.append((nr,nc))
print('unchanged zeros reachable distance stats',[(int(d),int(np.sum((A==0)&(B==0)&(D==d)))) for d in np.unique(D[(A==0)&(B==0)])]);
print('changed distances',[(int(d),int(np.sum((A==0)&(B==8)&(D==d)))) for d in np.unique(D[(A==0)&(B==8)])])

